1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:flutter/semantics.dart';
5	
6	import '../../../../core/design_tokens.dart';
7	import '../../../../core/widgets/app_button.dart';
8	import '../../domain/repositories/vault_repository.dart';
9	import '../widgets/pin_keypad.dart';
10	
11	/// `/vault` — the epic's one lock screen, shown whenever
12	/// `VaultRepository.currentStatus` isn't `VaultStatus.unlocked`
13	/// (`core/navigation/app_router.dart`'s `_redirect`). Auto-triggers the OS
14	/// biometric prompt once in [initState]; a successful
15	/// [VaultRepository.authenticate] call flips `currentStatus` to `unlocked`,
16	/// which — via `statusStream`/`refreshListenable` — re-runs the redirect and
17	/// navigates away from here on its own, so this widget never navigates
18	/// imperatively itself.
19	///
20	/// Story 2.2: every biometric failure (decline/cancel/any OS lockout — the
21	/// generic `authenticate()` catches already cover it, spec-2-2) falls
22	/// through to a real [PinKeypad] + error band, never a second biometric
23	/// "Tentar novamente" affordance (AC2). The "Usar PIN" ghost link reaches
24	/// the same keypad directly, with no error band, before any biometric
25	/// failure has happened. [VaultRepository.submitPin]'s own success emits
26	/// `VaultStatus.unlocked`, same as [VaultRepository.authenticate] — this
27	/// widget navigates away on that exactly the same way, with no branch for
28	/// "which path unlocked it".
29	class VaultLockScreen extends StatefulWidget {
30	  const VaultLockScreen({
31	    required this.vaultRepository,
32	    required this.attemptBiometricFirst,
33	    super.key,
34	  });
35	
36	  final VaultRepository vaultRepository;
37	
38	  /// Story 2.4 — `AccountSettingsRepository.currentBiometricEnabled`, read
39	  /// by `core/navigation/app_router.dart`'s `/vault` builder. `true`
40	  /// (including the default before the boot fetch resolves, Design Notes)
41	  /// auto-triggers [VaultRepository.authenticate] in [initState] exactly
42	  /// as before this story; `false` skips straight to the PIN keypad — PIN
43	  /// remains the access method regardless (Boundaries).
44	  final bool attemptBiometricFirst;
45	
46	  @override
47	  State<VaultLockScreen> createState() => _VaultLockScreenState();
48	}
49	
50	class _VaultLockScreenState extends State<VaultLockScreen> {
51	  static const _biometricFailureMessage =
52	      'Não foi possível reconhecer — digite seu PIN';
53	
54	  /// No specific copy is given anywhere in `docs/input/` for a PIN
55	  /// mismatch (the I/O matrix only specifies the `Failure` returned) —
56	  /// decided here (Design Notes), mirroring the biometric failure band's
57	  /// own tone.
58	  static const _pinMismatchMessage = 'PIN incorreto. Tente novamente.';
59	
60	  /// No specific copy is given anywhere in `docs/input/` for a
61	  /// `submitPin` call that never resolves (decided here, Design Notes) —
62	  /// review finding: without a bound, a hung secure-storage channel call
63	  /// would leave [_submittingPin] stuck `true` forever, permanently
64	  /// blocking every future attempt and contradicting the spec's own
65	  /// "never a dead end" boundary.
66	  static const _submitTimeoutMessage =
67	      'Não foi possível verificar o PIN. Tente novamente.';
68	
69	  static const _submitPinTimeout = Duration(seconds: 10);
70	
71	  bool _showPinKeypad = false;
72	  String? _errorMessage;
73	
74	  /// Re-entrancy guard for [_submitPin], also passed to [PinKeypad] as
75	  /// `enabled: !_submittingPin` — [PinKeypad] clears its own buffer and
76	  /// accepts new taps immediately after calling `onSubmit`, before the
77	  /// awaited [VaultRepository.submitPin] below resolves, so a fast second
78	  /// 4-digit entry could otherwise be accepted and then silently dropped
79	  /// here with no feedback; gating the keypad itself means it's never
80	  /// accepted in the first place.
81	  bool _submittingPin = false;
82	
83	  @override
84	  void initState() {
85	    super.initState();
86	    if (widget.attemptBiometricFirst) {
87	      _attemptAuthenticate();
88	    } else {
89	      // Story 2.4 — the preference is already `false` by the time this
90	      // screen builds: skip the OS biometric prompt entirely and show the
91	      // PIN keypad directly, with no error band (same "pre-failure" look
92	      // as tapping "Usar PIN" manually).
93	      _showPinKeypad = true;
94	    }
95	  }
96	
97	  Future<void> _attemptAuthenticate() async {
98	    final result = await widget.vaultRepository.authenticate();
99	    if (!mounted) {
100	      return;
101	    }
102	
103	    // On success, `currentStatus` is already `unlocked` and the router's
104	    // own `refreshListenable` will navigate away from `/vault` on its own —
105	    // this widget has nothing further to do (and may already be in the
106	    // process of being disposed by the time that happens).
107	    var shouldAnnounceFailure = false;
108	    result.match((_) {
109	      // If the user already reached the keypad manually (via "Usar
110	      // PIN") before this pending call resolved, this late failure must
111	      // never clobber whatever the keypad is currently showing — AC2's
112	      // "no second biometric-retry affordance" only concerns the
113	      // biometric view itself, which is no longer on screen.
114	      final alreadyOnKeypad = _showPinKeypad;
115	      shouldAnnounceFailure = !alreadyOnKeypad;
116	      if (!alreadyOnKeypad) {
117	        setState(() {
118	          _showPinKeypad = true;
119	          _errorMessage = _biometricFailureMessage;
120	        });
121	      }
122	    }, (_) {});
123	
124	    // `sendAnnouncement()` (see `_announce` below) is honored on both
125	    // Android and iOS — this app is iOS-only, where VoiceOver doesn't
126	    // reliably treat a live-region subtree update as an announcement on
127	    // its own, so the biometric->PIN transition is spoken explicitly
128	    // here rather than relying on any ambient live region.
129	    if (shouldAnnounceFailure && mounted) {
130	      await _announce(_biometricFailureMessage);
131	    }
132	  }
133	
134	  void _useManualPin() {
135	    setState(() {
136	      _showPinKeypad = true;
137	      _errorMessage = null;
138	    });
139	  }
140	
141	  @override
142	  void didUpdateWidget(covariant VaultLockScreen oldWidget) {
143	    super.didUpdateWidget(oldWidget);
144	    // Review finding: `attemptBiometricFirst` was only ever consulted
145	    // once, in `initState` — defensive future-proofing in case this
146	    // already-mounted widget is ever rebuilt with a new value (today,
147	    // nothing actually does: `app_router.dart` reads `currentBiometricEnabled`
148	    // fresh only when `/vault` is newly built, not while already resident
149	    // there — see its own doc comment). If that ever changes, e.g. a boot-
150	    // time `fetchBiometricEnabled()` resolving to `false` while `/vault` is
151	    // already mounted (with the default `true`) and already auto-triggered
152	    // the OS biometric prompt: that in-flight prompt can't be retracted
153	    // from here, but the preference can still be honored going forward: if
154	    // we're still waiting on it (haven't fallen through to the keypad yet),
155	    // switch to it proactively — exactly as if the user had tapped "Usar
156	    // PIN" themselves. A `false` -> `true` change is deliberately left
157	    // alone: re-triggering biometric out from under a user who's already
158	    // on the keypad (whether because it failed or because they chose "Usar
159	    // PIN") would be a surprise, not a fix, and PIN remains the access
160	    // method regardless either way (Boundaries).
161	    if (oldWidget.attemptBiometricFirst &&
162	        !widget.attemptBiometricFirst &&
163	        !_showPinKeypad) {
164	      _useManualPin();
165	    }
166	  }
167	
168	  Future<void> _submitPin(String pin) async {
169	    if (_submittingPin) {
170	      return;
171	    }
172	    // Review finding: previously left in place, a stale mismatch/timeout
173	    // message from a prior attempt lingered unchanged through this new
174	    // attempt, with nothing distinguishing "old error, nothing happening"
175	    // from "new attempt in flight" — cleared here so only this attempt's
176	    // own outcome (or the keypad's disabled/dimmed state) is visible.
177	    setState(() {
178	      _submittingPin = true;
179	      _errorMessage = null;
180	    });
181	    try {
182	      final result = await widget.vaultRepository
183	          .submitPin(pin)
184	          .timeout(_submitPinTimeout);
185	      if (!mounted) {
186	        return;
187	      }
188	      if (result.isLeft()) {
189	        // Mismatch: stays locked, no attempt cap — the keypad itself has
190	        // already cleared its own buffer by the time this runs
191	        // (PinKeypad's own contract), so the user can simply try again.
192	        setState(() => _errorMessage = _pinMismatchMessage);
193	        await _announce(_pinMismatchMessage);
194	      }
195	      // On a match (first-use or later), `currentStatus` is already
196	      // `unlocked` and the router navigates away on its own, same as a
197	      // successful `authenticate()`.
198	    } on TimeoutException {
199	      if (!mounted) {
200	        return;
201	      }
202	      // Bounds the wait so a hung secure-storage call can never leave
203	      // `_submittingPin` stuck `true` forever — the `finally` below still
204	      // runs because this `await` has now actually completed (with a
205	      // thrown `TimeoutException`), same retryable outcome as a mismatch.
206	      setState(() => _errorMessage = _submitTimeoutMessage);
207	      await _announce(_submitTimeoutMessage);
208	    } finally {
209	      if (mounted) {
210	        setState(() => _submittingPin = false);
211	      } else {
212	        _submittingPin = false;
213	      }
214	    }
215	  }
216	
217	  Future<void> _announce(String message) async {
218	    if (!mounted) {
219	      return;
220	    }
221	    await SemanticsService.sendAnnouncement(
222	      View.of(context),
223	      message,
224	      TextDirection.ltr,
225	    );
226	  }
227	
228	  @override
229	  Widget build(BuildContext context) {
230	    // No ambient `Semantics(liveRegion: true)` wrapper here — it would
231	    // re-trigger on every single digit tap inside `PinKeypad` (its own
232	    // `_ProgressDots` label changes each tap), not just the two
233	    // transitions that actually need announcing. Those two (biometric
234	    // failure, PIN mismatch) are already covered explicitly and reliably
235	    // by `_announce()` below.
236	    //
237	    // Tela 0.1b/c (the PIN keypad) is top-aligned under its own
238	    // `pinScreenPadding`, unlike Tela 0.1 (biometric), which stays
239	    // centered under the generic `screenPadding` — matching each state's
240	    // own layout in `cerne-prototype.html` (Story 2.2 correction).
241	    return Scaffold(
242	      backgroundColor: DesignTokens.colorSurfaceBg,
243	      body: _showPinKeypad
244	          ? Padding(
