18	/// Covers spec-2-1's I/O & Edge-Case Matrix exactly:
19	/// - biometrics succeed -> `unlocked` emitted, `Right(unit)`.
20	/// - biometrics fail/cancelled/unavailable (`false` or a thrown
21	///   `LocalAuthException`) -> status stays `locked`,
22	///   `Left(Failure.malformedResponse(...))`, no crash.
23	///
24	/// Plus spec-2-2's own additions:
25	/// - `submitPin`, no PIN stored yet -> stores it, `unlocked`, `Right(unit)`.
26	/// - `submitPin`, stored PIN matches -> `unlocked`, `Right(unit)`.
27	/// - `submitPin`, stored PIN mismatch -> stays `locked`,
28	///   `Left(Failure.malformedResponse(...))`, no attempt cap.
29	///
30	/// Plus spec-2-3's own additions (see the dedicated
31	/// `didChangeAppLifecycleState() — idle re-authentication` group below):
32	/// idle re-lock after backgrounding for >= 5 minutes while unlocked, no
33	/// re-lock below the threshold, no duplicate emission while already
34	/// locked, and no crash on a bare `resumed` with no prior `paused`.
35	void main() {
36	  // Story 2.3's constructor now calls `WidgetsBinding.instance.
37	  // addObserver(this)` — unlike the rest of this file's plain `test()`
38	  // blocks (no `testWidgets`, which would initialize this implicitly), the
39	  // binding needs explicit, idempotent initialization up front.
40	  TestWidgetsFlutterBinding.ensureInitialized();
41	
42	  late MockLocalAuthentication mockLocalAuthentication;
43	  late MockFlutterSecureStorage mockSecureStorage;
44	  late VaultRepositoryImpl repository;
45	
46	  setUp(() {
47	    mockLocalAuthentication = MockLocalAuthentication();
48	    mockSecureStorage = MockFlutterSecureStorage();
49	    repository = VaultRepositoryImpl(
50	      localAuthentication: mockLocalAuthentication,
51	      secureStorage: mockSecureStorage,
52	    );
53	  });
54	
55	  // Each VaultRepositoryImpl registers itself as a WidgetsBindingObserver
56	  // in its constructor (Story 2.3) — dispose() here removes it again so a
57	  // stale observer doesn't linger on the shared
58	  // TestWidgetsFlutterBinding.instance across test runs.
59	  tearDown(() => repository.dispose());
60	
61	  /// Same rationale as `session_repository_impl_test.dart`'s own
62	  /// `emittedDuring` helper, with one difference: unlike
63	  /// `SessionRepository.statusStream` (nullable, no replay until the first
64	  /// emission), [VaultRepository.statusStream] always synchronously
65	  /// replays the current (never-null) [VaultStatus] to a brand-new
66	  /// listener — so the first element this helper's subscription ever sees
67	  /// is always that initial replay, not an emission caused by [act]. It's
68	  /// drained and discarded here so the returned list reflects only
69	  /// emissions [act] itself caused.
70	  Future<List<VaultStatus>> emittedDuring(Future<void> Function() act) async {
71	    final emitted = <VaultStatus>[];
72	    final subscription = repository.statusStream.listen(emitted.add);
73	    await Future<void>.delayed(Duration.zero);
74	    emitted.clear();
75	    await act();
76	    await Future<void>.delayed(Duration.zero);
77	    await subscription.cancel();
78	    return emitted;
79	  }
80	
81	  group('VaultStatus.currentStatus — non-nullable, known at construction', () {
82	    test('currentStatus is VaultStatus.locked before any authenticate() '
83	        'call — no async warm-up, unlike SessionStatus (Design Notes)', () {
84	      expect(repository.currentStatus, VaultStatus.locked);
85	    });
86	
87	    test(
88	      'a listener that subscribes before any authenticate() call still '
89	      'immediately sees VaultStatus.locked, not nothing until the first '
90	      'emission (Stream.multi replay, mirrors SessionRepositoryImpl)',
91	      () async {
92	        final status = await repository.statusStream.first;
93	
94	        expect(status, VaultStatus.locked);
95	      },
96	    );
97	  });
