16	/// plain fake (not mocktail) so `authenticate()`'s resolution can be held
17	/// open with a `Completer`, which this suite needs to observe the screen's
18	/// mid-flight state, plus a scriptable `submitPin()` for the PIN-flow
19	/// cases (spec-2-2).
20	class _FakeVaultRepository implements VaultRepository {
21	  VaultStatus _status = VaultStatus.locked;
22	  final _controller = StreamController<VaultStatus>.broadcast();
23	
24	  /// Controls what the NEXT `authenticate()` call resolves to. Defaults to
25	  /// `false` (a quiet decline), matching `app_router_test.dart`'s own
26	  /// default so a bare `pumpWidget` never silently unlocks.
27	  bool authenticateSucceeds = false;
28	
29	  /// The `Failure.message` the next failing `authenticate()` call
30	  /// returns — lets a test simulate a distinctly-flavored failure (e.g.
31	  /// an OS-lockout code) while still exercising the real production
32	  /// behavior, which maps every `LocalAuthException`/`false` result to
33	  /// the same generic `Failure.malformedResponse` with no code-specific
34	  /// branch (review finding: proves the "same routing regardless of
35	  /// flavor" claim instead of only asserting it by comment).
36	  String authenticateFailureMessage = 'fake: biometrics declined';
37	
38	  /// Lets a test hold `authenticate()` unresolved to inspect a mid-flight
39	  /// frame before letting it settle.
40	  Completer<void>? authenticateGate;
41	
42	  int authenticateCallCount = 0;
43	
44	  /// The one PIN `submitPin()` treats as "stored" — `null` means no PIN
45	  /// has been stored yet, matching `VaultRepositoryImpl`'s own set-on-
46	  /// first-use behavior (spec-2-2 Design Notes).
47	  String? storedPin;
48	
49	  int submitPinCallCount = 0;
50	
51	  /// Lets a test hold `submitPin()` unresolved — mirrors
52	  /// [authenticateGate]'s own rationale, used to prove `VaultLockScreen`'s
53	  /// re-entrancy guard against a fast second PIN entry firing a second
54	  /// concurrent call.
55	  Completer<void>? submitPinGate;
56	
57	  @override
58	  VaultStatus get currentStatus => _status;
59	
60	  @override
61	  Stream<VaultStatus> get statusStream => _controller.stream;
62	
63	  @override
64	  Future<Either<Failure, Unit>> authenticate() async {
65	    authenticateCallCount += 1;
66	    final gate = authenticateGate;
67	    if (gate != null) {
68	      await gate.future;
69	    }
70	    if (authenticateSucceeds) {
71	      _status = VaultStatus.unlocked;
72	      _controller.add(_status);
73	      return right(unit);
74	    }
75	    return left(Failure.malformedResponse(message: authenticateFailureMessage));
76	  }
77	
78	  @override
79	  Future<Either<Failure, Unit>> submitPin(String pin) async {
80	    submitPinCallCount += 1;
81	    final gate = submitPinGate;
82	    if (gate != null) {
83	      await gate.future;
84	    }
85	    if (storedPin == null) {
86	      storedPin = pin;
87	      _status = VaultStatus.unlocked;
88	      _controller.add(_status);
89	      return right(unit);
90	    }
91	    if (storedPin == pin) {
92	      _status = VaultStatus.unlocked;
93	      _controller.add(_status);
94	      return right(unit);
95	    }
96	    return left(const Failure.malformedResponse(message: 'fake: PIN mismatch'));
97	  }
98	
99	  // Story 8.4 — not exercised by this suite, same trivial rationale this
100	  // fake's other untouched members already follow.
101	  @override
102	  void lock() {
103	    _status = VaultStatus.locked;
104	    _controller.add(_status);
105	  }
106	
107	  @override
108	  Future<void> dispose() => _controller.close();
109	}
110	
111	Widget _wrap(
112	  VaultRepository vaultRepository, {
113	  bool attemptBiometricFirst = true,
114	}) {
115	  return MaterialApp(
116	    home: VaultLockScreen(
117	      vaultRepository: vaultRepository,
118	      attemptBiometricFirst: attemptBiometricFirst,
119	    ),
120	  );
121	}
