123	Future<void> _enterPin(WidgetTester tester, String pin) async {
124	  for (final digit in pin.split('')) {
125	    await tester.tap(find.text(digit));
126	    await tester.pump();
127	  }
128	  // Auto-advance fires 350ms after the 4th digit (UX-DR14).
129	  await tester.pump(const Duration(milliseconds: 350));
130	}
