3	import 'package:flutter/material.dart';
4	import 'package:flutter_localizations/flutter_localizations.dart';
5	import 'package:fpdart/fpdart.dart' hide State;
6	import 'package:go_router/go_router.dart';
7	
8	import 'core/di/injection_container.dart';
9	import 'core/failure/failure.dart';
10	import 'core/navigation/app_router.dart';
11	import 'core/navigation/expiry_overlay_host.dart';
12	import 'features/account/domain/repositories/account_settings_repository.dart';
13	import 'features/auth/domain/repositories/session_repository.dart';
14	import 'features/vault/domain/repositories/vault_repository.dart';
15	
16	Future<void> main() async {
17	  WidgetsFlutterBinding.ensureInitialized();
18	  try {
19	    await setupCoreDependencies();
20	  } catch (error) {
21	    debugPrint(
22	      'Cerne failed to start: could not load .env ($error). Copy '
23	      '.env.example to .env and fill in FUNCTIONS_BASE_URL + '
24	      'SUPABASE_ANON_KEY before running the app.',
25	    );
26	    rethrow;
27	  }
28	  // Review finding: `app_router.dart`'s `_redirect` composes the vault
29	  // gate (AD-14) strictly first, synchronously, ahead of everything else —
30	  // it routes to `/vault` on the very first redirect evaluation, before
31	  // `CerneApp`'s own fire-and-forget boot fetch below could ever resolve.
32	  // `/vault`'s builder reads `currentBiometricEnabled` synchronously at
33	  // that moment, so without this awaited (bounded) fetch here, every cold
34	  // start reads the untouched default (`true`) regardless of what the user
35	  // actually set — not the "one-time, benign gap on a slow-network cold
36	  // boot" it looked like. Bounded so a hung network call can't delay app
37	  // launch indefinitely; on timeout/failure, `currentBiometricEnabled` is
38	  // simply left at its documented default, same outcome as before this
39	  // fix.
40	  await sl<AccountSettingsRepository>()
41	      .fetchBiometricEnabled()
42	      .timeout(const Duration(seconds: 2), onTimeout: () => right(unit))
43	      .catchError(_asUnchangedPreference);
44	  runApp(const CerneApp());
45	}
46	
47	// `catchError`'s handler must still complete the Future with a value of
48	// its declared type (`Either<Failure, Unit>`) — a `void`-returning handler
49	// would try to complete it with `null`, which isn't assignable to that
50	// non-nullable type and would itself throw. Top-level (not a
51	// `_CerneAppState` method) so both `main()`'s own awaited fetch above and
52	// `CerneApp.initState`'s fire-and-forget one below can share it.
53	Either<Failure, Unit> _asUnchangedPreference(
54	  Object error,
55	  StackTrace stackTrace,
56	) {
57	  debugPrint('Cerne: fetchBiometricEnabled() threw unexpectedly ($error)');
58	  return left(Failure.malformedResponse(message: error.toString()));
59	}
60	
61	/// Root widget. Portrait-only, light-mode-only, fixed 390x844 frame — no
62	/// breakpoint, landscape or dark-mode path anywhere in the app (per the
63	/// epic's UX constraints; the portrait lock itself lives in
64	/// `ios/Runner/Info.plist`, Story 1.6).
65	///
66	/// Story 1.6 scope: the ad-hoc `StreamBuilder`/`Navigator.push` shell
67	/// Stories 1.3-1.5 built this on top of is replaced by the one real
68	/// `go_router` (`core/navigation/app_router.dart`) plus its
69	/// `ExpiryOverlayHost` wrapper — [restoreSession] still fires once at boot
70	/// here (unchanged from Story 1.4), but every screen transition and the
71	/// expiry overlay's own "Entrar novamente" now go through that router
72	/// instead of an imperative `Navigator`.
73	class CerneApp extends StatefulWidget {
74	  const CerneApp({super.key});
75	
76	  @override
77	  State<CerneApp> createState() => _CerneAppState();
78	}
79	
80	class _CerneAppState extends State<CerneApp> {
81	  late final SessionRepository _sessionRepository;
82	  late final VaultRepository _vaultRepository;
83	  late final AccountSettingsRepository _accountSettingsRepository;
84	  late final GoRouter _router;
85	
86	  // Created here (not left for `GoRouter` to generate internally) and
87	  // passed to both `buildAppRouter` and `ExpiryOverlayHost` below, so the
88	  // latter can reach the Navigator's own `BuildContext` through this
89	  // public, documented key instead of reaching into `GoRouter`'s internal
90	  // `routerDelegate`.
91	  final GlobalKey<NavigatorState> _navigatorKey = GlobalKey<NavigatorState>(
92	    debugLabel: 'root',
93	  );
94	
95	  @override
96	  void initState() {
97	    super.initState();
98	    _sessionRepository = sl<SessionRepository>();
99	    _vaultRepository = sl<VaultRepository>();
100	    _accountSettingsRepository = sl<AccountSettingsRepository>();
101	    _router = buildAppRouter(
102	      vaultRepository: _vaultRepository,
103	      sessionRepository: _sessionRepository,
104	      accountSettingsRepository: _accountSettingsRepository,
105	      navigatorKey: _navigatorKey,
106	    );
107	    // Fire-and-forget: the outcome reaches the UI through
108	    // `SessionRepository.currentStatus`/`statusStream` (which the router's
109	    // `redirect`/`refreshListenable` already watch), not through this
110	    // call's return value. `restoreSession()` already maps every internal
111	    // failure to `Left`/an `unauthenticated` emission and never throws.
112	    // This `catchError` is NOT a UI recovery path — its handler's return
113	    // value is discarded by `unawaited` and never reaches `statusStream`.
114	    // It exists purely so a future regression that broke the "never
115	    // throws" contract above would surface as a logged message instead of
116	    // an unhandled zone exception.
117	    unawaited(
118	      _sessionRepository.restoreSession().catchError(_asUnauthenticated),
119	    );
120	    // Story 2.4 — boot-time read of `biometricEnabled`, same
121	    // fire-and-forget rationale as `restoreSession()` above: the outcome
122	    // reaches `VaultLockScreen` through `AccountSettingsRepository.
123	    // currentBiometricEnabled`/`biometricEnabledStream` (which the router's
124	    // `refreshListenable` already watches), never through this call's
125	    // return value, and a failure leaves `currentBiometricEnabled`
126	    // unchanged (I/O matrix) rather than surfacing anywhere.
127	    unawaited(
128	      _accountSettingsRepository.fetchBiometricEnabled().catchError(
129	        _asUnchangedPreference,
130	      ),
131	    );
132	  }
133	
134	  @override
135	  void dispose() {
136	    _router.dispose();
137	    super.dispose();
138	  }
139	
140	  // `catchError`'s handler must still complete the Future with a value of
141	  // its declared type (`Either<Failure, Unit>`) — a `void`-returning
142	  // handler would try to complete it with `null`, which isn't assignable
143	  // to that non-nullable type and would itself throw.
144	  static Either<Failure, Unit> _asUnauthenticated(
145	    Object error,
146	    StackTrace stackTrace,
147	  ) {
148	    debugPrint('CerneApp: restoreSession() threw unexpectedly ($error)');
149	    return left(Failure.malformedResponse(message: error.toString()));
150	  }
151	
152	  @override
153	  Widget build(BuildContext context) {
154	    return MaterialApp.router(
155	      debugShowCheckedModeBanner: false,
156	      // Review finding (spec-7-1): every hand-written string in the app is
157	      // already PT-BR, but `showDateRangePicker` (the export period
158	      // picker) is Flutter's own built-in widget — without these, it falls
159	      // back to US English ("CANCEL"/"SELECT RANGE") on an otherwise
160	      // all-Portuguese screen.
161	      locale: const Locale('pt', 'BR'),
162	      localizationsDelegates: const [
163	        GlobalMaterialLocalizations.delegate,
164	        GlobalWidgetsLocalizations.delegate,
165	        GlobalCupertinoLocalizations.delegate,
166	      ],
167	      supportedLocales: const [Locale('pt', 'BR')],
168	      routerConfig: _router,
169	      builder: (context, child) => ExpiryOverlayHost(
170	        sessionRepository: _sessionRepository,
171	        router: _router,
172	        navigatorKey: _navigatorKey,
173	        child: child!,
174	      ),
175	    );
176	  }
177	}
